import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';
import dgram from 'node:dgram';
import { launchChromium } from './test-browser.mjs';
const here = path.dirname(fileURLToPath(import.meta.url));
const browser = await launchChromium();
const page = await browser.newPage({ viewport: { width: 1512, height: 1080 }, acceptDownloads: true });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
const report = {};
try {
  await page.goto('http://127.0.0.1:8787/system.html?clean&test&look=sixDDS');
  await page.waitForFunction(() => window.parte2 && document.getElementById('system-loading').hidden, null, { timeout: 90000 });
  await page.evaluate(() => { window.system = window.parte2; });
  report.bootstrap = 'Unmodified system/app.js';
  report.initial = await page.evaluate(() => ({ parameters: system.params.list().length, inputs: document.querySelectorAll('[data-param]').length,
    decks: document.querySelectorAll('[data-deck]').length, mappings: system.mapper.list().length,
    overflow: document.documentElement.scrollWidth > innerWidth, gpuErrors: system.engine.errors }));
  assert.equal(report.initial.decks, 7); assert.ok(report.initial.parameters > 300); assert.equal(report.initial.overflow, false);
  assert.equal(await page.evaluate(() => system.params.get('transport.playing')), false);
  await page.click('#system-play'); assert.equal(await page.evaluate(() => system.params.get('transport.playing')), true);
  await page.click('#system-play'); assert.equal(await page.evaluate(() => system.params.get('transport.playing')), false);
  await page.click('#tab-midi');
  assert.equal(await page.locator('.mapping-row').count(), 20);
  assert.equal(await page.locator('.mapping-editor').count(), 0);
  const firstMapping = await page.locator('.mapping-row').first().getAttribute('data-mapping');
  await page.click('#mapping-next'); assert.notEqual(await page.locator('.mapping-row').first().getAttribute('data-mapping'), firstMapping);
  await page.selectOption('#mapping-profile-filter', 'web');
  assert.equal(await page.locator('.mapping-profile.web').count(), 20);
  const csvEvent = page.waitForEvent('download'); await page.click('#mapping-csv');
  await (await csvEvent).saveAs(path.join(here, 'parte2-controles-midi.csv'));
  await writeFile(path.join(here, 'default-mappings.json'), await page.evaluate(() => system.mapper.exportJson()));
  report.defaultMappings = await page.evaluate(() => ({ total: system.mapper.list().length,
    web: system.mapper.list().filter(r => r.origin === 'webextension').length,
    targets: new Set(system.mapper.list().map(r => r.target)).size }));
  assert.equal(report.defaultMappings.targets, report.initial.parameters);
  await page.evaluate(() => {
    const row = system.mapper.list().find(r => r.id === 'web.cc.final.fx2');
    system.dispatchMidi([0xb0 + row.source.channel - 1, row.source.cc, 127]);
  });
  assert.equal(await page.evaluate(() => system.params.get('final.fx2')), 1);
  await page.selectOption('#mapping-profile-filter', 'all');
  await page.waitForFunction(() => system.osc?.readyState === EventSource.OPEN);
  const oscAddress = `/test/parte2/${process.pid}`;
  await page.evaluate(address => system.mapper.setMappings([...system.mapper.list(), { id: 'test.osc.route',
    source: { kind: 'osc', address }, target: 'final.fx2', mode: 'set', valueFrom: 'argument' }]), oscAddress);
  const oscString = value => { const b = Buffer.from(value + '\0'); const padded = Buffer.alloc(Math.ceil(b.length / 4) * 4); b.copy(padded); return padded; };
  const f = Buffer.alloc(4); f.writeFloatBE(.375);
  const socket = dgram.createSocket('udp4');
  await new Promise((resolve, reject) => socket.send(Buffer.concat([oscString(oscAddress), oscString(',f'), f]), 1002, '127.0.0.1', error => error ? reject(error) : resolve()));
  socket.close();
  await page.waitForFunction(() => system.params.get('final.fx2') === .375);
  report.osc = { udpPort: 1002, path: 'UDP → SSE → Mapper → public parameter', value: .375 };
  await page.evaluate(() => system.mapper.setMappings(system.mapper.list().filter(r => r.id !== 'test.osc.route')));
  await page.fill('#system-scene', '66'); await page.locator('#system-scene').press('Tab');
  assert.equal(await page.evaluate(() => system.params.get('scene.current')), 66);
  await page.click('[data-look="final"]');
  assert.equal(await page.evaluate(() => system.params.get('scene.automation')), false);
  await page.fill('#parameter-search', 'final.fx2');
  assert.equal(await page.locator('.param-row:visible').count(), 1);
  const fx2 = page.locator('.param-row [data-param="final.fx2"][type="number"]');
  await fx2.fill('0.35'); await fx2.press('Tab');
  assert.equal(await page.evaluate(() => system.params.get('final.fx2')), .35);
  await page.fill('#parameter-search', 'composition.warp.amount');
  assert.equal(await page.locator('.param-row:visible').count(), 1);
  await page.locator('[data-param="composition.warp.amount"][type="number"]').fill('0.27');
  await page.locator('[data-param="composition.warp.amount"][type="number"]').press('Tab');
  assert.equal(await page.evaluate(() => system.params.get('composition.warp.amount')), .27);
  await page.click('#tab-midi');
  await page.selectOption('#mapping-target', 'final.fx1'); await page.click('#mapping-learn');
  assert.equal(await page.locator('#learn-status').isVisible(), true);
  await page.evaluate(() => system.dispatchMidi([0xb1, 17, 96]));
  assert.equal(await page.locator('#learn-status').isVisible(), false);
  await page.evaluate(() => system.dispatchMidi([0xb1, 17, 127]));
  assert.equal(await page.evaluate(() => system.params.get('final.fx1')), 1);
  const row = page.locator('.mapping-row').last(); await row.locator('summary').first().click();
  const enabled = row.locator('.mapping-editor input[type="checkbox"]').first();
  await enabled.uncheck();
  await page.evaluate(() => { system.params.set('final.fx1', 0); system.dispatchMidi([0xb1, 17, 127]); });
  assert.equal(await page.evaluate(() => system.params.get('final.fx1')), 0);
  await page.evaluate(() => { for(let i=0;i<60;i++) system.dispatchMidi([0xb2,5,i]); });
  assert.equal(await page.locator('#midi-monitor li').count(), 50);
  report.learn = await page.evaluate(() => system.mapper.list().at(-1));
  await page.click('#tab-media'); await page.fill('#catalog-search', '');
  assert.equal(await page.locator('.catalog-entry').count(), await page.evaluate(() => system.manifest.clips.length));
  assert.ok(await page.locator('.catalog-badge.missing').count() > 0);
  await page.click('#tab-scenes'); await page.click('#scene-save');
  await page.evaluate(() => system.params.set('final.fx1', .44)); await page.click('#scene-recall');
  assert.equal(await page.evaluate(() => system.params.get('final.fx1')), 0);
  await page.click('#system-blackout'); assert.equal(await page.evaluate(() => system.params.get('output.blackout')), true);
  await page.click('#system-blackout');
  await page.evaluate(async () => {
    system.params.set('output.resolution', '1920x600'); system.params.set('final.flash', false);
    system.params.set('final.fx1', 0); system.params.set('final.fx2', 0); system.params.set('composition.warp.amount', -.31);
    await system.step(85);
  });
  const downloadEvent = page.waitForEvent('download'); await page.click('#system-capture'); const download = await downloadEvent;
  report.png = await page.evaluate(async () => { const image = await createImageBitmap(await system.capture()); return [image.width,image.height]; });
  assert.deepEqual(report.png, [1920,600]);
  await mkdir(path.join(here, '..', 'captures'), { recursive:true });
  await download.saveAs(path.join(here, '..', 'captures', 'system-ui-output.png'));
  await page.click('#tab-effects'); await page.screenshot({path:path.join(here,'..','captures','system-ui-desktop.png'),fullPage:true});
  await page.setViewportSize({width:390,height:844});
  report.mobile = await page.evaluate(() => ({ width:innerWidth, scrollWidth:document.documentElement.scrollWidth, canvas:document.getElementById('system-canvas').getBoundingClientRect().toJSON() }));
  assert.equal(report.mobile.scrollWidth, report.mobile.width);
  await page.screenshot({path:path.join(here,'..','captures','system-ui-mobile.png'),fullPage:true});
  report.errors = errors; report.gpuErrors = await page.evaluate(() => system.engine.errors);
  assert.deepEqual(errors, []); assert.deepEqual(report.gpuErrors, []);
  await writeFile(path.join(here,'..','captures','system-ui-validation.json'),JSON.stringify(report,null,2));
  console.log(JSON.stringify(report,null,2));
} finally { await browser.close(); }
